/**
 * Response shapes against Stripe's OpenAPI specs, at 2024-06-20 and at 2026-08-26.dahlia.
 *
 * Every object is created the way an application creates it (the real SDK; Checkout completed on
 * the hosted page) and its top-level keys are compared with test/fixtures/spec-keys.json
 * (generated by scripts/build-spec-keys.mjs): every always-present key is there, null only where
 * the spec allows null, includable keys only when expanded, and no key the spec does not define.
 * Embedded subscription items and invoice lines, and the `data.object` of every delivered event,
 * are checked the same way. Payloads of events are checked at the webhook endpoint's version.
 */
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { startServer, webhookReceiver } from './helpers.js';

const SPEC = JSON.parse(readFileSync(new URL('./fixtures/spec-keys.json', import.meta.url), 'utf8')).versions;
const OLD = '2024-06-20';
const LATEST = '2026-08-26.dahlia';
const SECRET = 'whsec_shapes_endpoint_secret';
const DAY = 86400;

/**
 * Keys the server deliberately emits outside a version's spec. The portal configuration keeps its
 * full current shape at every version: every portal change in the supported range is
 * non-breaking (see README "Uncertain behaviour"), so its newer keys (`name`) are allowed on older
 * versions.
 */
const EXTRA_ALLOWED = { 'billing_portal.configuration': SPEC[LATEST]['billing_portal.configuration'] };

/**
 * Differences between `obj` and the spec key set of `type` at `version`, as readable strings.
 * `expanded` lists includable keys the request asked for.
 */
function shapeProblems(obj, type, version, { expanded = [], where = type } = {}) {
  const spec = SPEC[version][type];
  const extra = EXTRA_ALLOWED[type];
  const known = new Set([...spec.required, ...spec.optional, ...spec.includable, ...(extra ? [...extra.required, ...extra.optional] : [])]);
  const nullable = new Set([...spec.nullable, ...(extra?.nullable ?? [])]);
  const problems = [];
  if (!obj || typeof obj !== 'object') return [`${where}: not an object (${JSON.stringify(obj)})`];
  for (const key of spec.required) if (!(key in obj)) problems.push(`${where}: missing required key "${key}"`);
  for (const key of spec.includable) {
    if (key in obj && !expanded.includes(key)) problems.push(`${where}: includable key "${key}" present without expand`);
  }
  for (const [key, value] of Object.entries(obj)) {
    if (!known.has(key)) problems.push(`${where}: key "${key}" is not in the ${version} spec`);
    else if (value === null && !nullable.has(key)) problems.push(`${where}: "${key}" is null but not nullable`);
  }
  return problems;
}

/** Checks an object and the lists embedded in it (subscription items, invoice lines). */
function deepProblems(obj, type, version, opts = {}) {
  const problems = shapeProblems(obj, type, version, opts);
  const where = opts.where ?? type;
  if (type === 'subscription' && obj?.items?.data) {
    obj.items.data.forEach((item, i) => problems.push(...shapeProblems(item, 'subscription_item', version, { where: `${where}.items.data[${i}]` })));
  }
  if (type === 'invoice' && obj?.lines?.data) {
    obj.lines.data.forEach((line, i) => problems.push(...shapeProblems(line, 'line_item', version, { where: `${where}.lines.data[${i}]` })));
  }
  return problems;
}

async function postForm(url, fields) {
  const res = await fetch(url, {
    method: 'POST',
    body: new URLSearchParams(fields).toString(),
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    redirect: 'manual',
  });
  return { status: res.status, location: res.headers.get('location'), text: await res.text() };
}

/**
 * Builds one of every object at `version` (the SDK's Stripe-Version) on a server with the account
 * default left at its latest version, and a webhook endpoint pinned to `version`.
 */
async function world(version) {
  const hooks = await webhookReceiver();
  const t = await startServer({ webhooks: [{ url: hooks.url, secret: SECRET, apiVersion: version }] });
  const stripe = t.stripe(t.key, { apiVersion: version });
  const o = {};
  o.customer = await stripe.customers.create({ email: 'jenny@example.com', name: 'Jenny Rosen' });
  o.product = await stripe.products.create({ name: 'Pro' });
  o.price = await stripe.prices.create({ product: o.product.id, unit_amount: 3000, currency: 'usd', recurring: { interval: 'month' } });
  o.paymentMethod = await stripe.paymentMethods.attach('pm_card_visa', { customer: o.customer.id });
  o.openSession = await stripe.checkout.sessions.create({
    mode: 'subscription',
    customer: o.customer.id,
    line_items: [{ price: o.price.id, quantity: 1 }],
    success_url: 'https://example.com/ok?session={CHECKOUT_SESSION_ID}',
    cancel_url: 'https://example.com/cancel',
  });
  const paid = await postForm(o.openSession.url, { card_number: '4242424242424242' });
  if (paid.status !== 303) throw new Error(`hosted Checkout answered ${paid.status}: ${paid.text.slice(0, 500)}`);
  o.completedSession = await stripe.checkout.sessions.retrieve(o.openSession.id);
  o.subscription = await stripe.subscriptions.retrieve(o.completedSession.subscription);
  o.subscriptionItem = await stripe.subscriptionItems.retrieve(o.subscription.items.data[0].id);
  o.invoice = await stripe.invoices.retrieve(o.subscription.latest_invoice);
  o.invoiceLines = (await stripe.invoices.listLineItems(o.invoice.id)).data;
  o.schedule = await stripe.subscriptionSchedules.create({ from_subscription: o.subscription.id });
  // business_profile is required before 2024-10-28.acacia.
  o.portalConfiguration = await stripe.billingPortal.configurations.create({
    business_profile: { privacy_policy_url: 'https://example.com/privacy' },
    features: { invoice_history: { enabled: true } },
  });
  o.portalSession = await stripe.billingPortal.sessions.create({ customer: o.customer.id, return_url: 'https://example.com/account' });
  o.testClock = await stripe.testHelpers.testClocks.create({ frozen_time: Math.floor(Date.now() / 1000) });
  o.events = (await stripe.events.list({ limit: 100 })).data;
  await t.server.settle();
  o.delivered = hooks.deliveries.map((d) => stripe.webhooks.constructEvent(d.rawBody, d.headers['stripe-signature'], SECRET));
  return { t, stripe, o };
}

const CASES = [
  ['customer', (o) => [['customer', o.customer]]],
  ['product', (o) => [['product', o.product]]],
  ['price', (o) => [['price', o.price]]],
  ['payment_method', (o) => [['payment_method', o.paymentMethod]]],
  [
    'checkout.session',
    (o) => [
      ['checkout.session', o.openSession, 'open session'],
      ['checkout.session', o.completedSession, 'completed session'],
    ],
  ],
  ['subscription', (o) => [['subscription', o.subscription]]],
  ['subscription_item', (o) => [['subscription_item', o.subscriptionItem]]],
  ['subscription_schedule', (o) => [['subscription_schedule', o.schedule]]],
  ['invoice', (o) => [['invoice', o.invoice]]],
  ['line_item', (o) => o.invoiceLines.map((line, i) => ['line_item', line, `invoices.listLineItems[${i}]`])],
  ['billing_portal.configuration', (o) => [['billing_portal.configuration', o.portalConfiguration]]],
  ['billing_portal.session', (o) => [['billing_portal.session', o.portalSession]]],
  ['test_helpers.test_clock', (o) => [['test_helpers.test_clock', o.testClock]]],
];

describe.each([OLD, LATEST])('shapes at %s', (version) => {
  it.each(CASES)('%s has exactly the spec keys', async (_, pick) => {
    const { o } = await world(version);
    const problems = pick(o).flatMap(([type, obj, where]) => deepProblems(obj, type, version, { where: where ?? type }));
    expect(problems).toEqual([]);
  });

  it('includable keys appear when expanded, and only then', async () => {
    const { stripe, o } = await world(version);
    const customer = await stripe.customers.retrieve(o.customer.id, { expand: ['subscriptions', 'tax_ids', 'sources'] });
    const session = await stripe.checkout.sessions.retrieve(o.completedSession.id, { expand: ['line_items'] });
    const problems = [
      ...shapeProblems(customer, 'customer', version, { expanded: ['subscriptions', 'tax_ids', 'sources'] }),
      ...shapeProblems(session, 'checkout.session', version, { expanded: ['line_items'] }),
    ];
    expect(problems).toEqual([]);
    expect(Object.keys(customer)).toEqual(expect.arrayContaining(['subscriptions', 'tax_ids', 'sources']));
    expect(session.line_items.object).toBe('list');
  });

  it('events listed through the API have the event keys', async () => {
    const { o } = await world(version);
    expect(o.events.length).toBeGreaterThan(0);
    // GET /v1/events renders each event at its own api_version (the account default, latest),
    // whatever the request's Stripe-Version; the envelope is checked at that version.
    const problems = o.events.flatMap((e) => shapeProblems(e, 'event', e.api_version === OLD ? OLD : LATEST, { where: `event ${e.type}` }));
    expect(problems).toEqual([]);
  });

  it(`events delivered to an endpoint pinned to ${version} have the ${version} shapes`, async () => {
    const { o } = await world(version);
    expect(o.delivered.length).toBeGreaterThan(0);
    const problems = [];
    for (const e of o.delivered) {
      if (e.api_version !== version) problems.push(`event ${e.type}: api_version ${e.api_version}, expected ${version}`);
      problems.push(...shapeProblems(e, 'event', version, { where: `event ${e.type}` }));
      const type = e.data.object.object;
      // Payloads are the minimal form: no includable keys (`expanded` stays empty).
      if (SPEC[version][type]) problems.push(...deepProblems(e.data.object, type, version, { where: `${e.type} data.object` }));
    }
    expect(problems).toEqual([]);
  });
});

/**
 * The states a Billing integration goes through, at `version`: Checkout without a customer and with
 * a trial, an expired session, an upgrade invoiced at once, cancel at period end, an immediate
 * cancel, a failed renewal (past_due, open invoice), a released and a canceled schedule, an
 * advanced test clock and a portal session with a flow. Every object is then read back through
 * the list endpoints, and every delivered event payload is checked at the endpoint's version.
 */
async function lifecycle(version) {
  const hooks = await webhookReceiver();
  const t = await startServer({ webhooks: [{ url: hooks.url, secret: SECRET, apiVersion: version }] });
  const stripe = t.stripe(t.key, { apiVersion: version });
  const account = t.account();
  const basicProduct = await stripe.products.create({ name: 'Basic' });
  const proProduct = await stripe.products.create({ name: 'Pro' });
  const basic = await stripe.prices.create({ product: basicProduct.id, unit_amount: 1000, currency: 'usd', recurring: { interval: 'month' } });
  const pro = await stripe.prices.create({ product: proProduct.id, unit_amount: 3000, currency: 'usd', recurring: { interval: 'month' } });

  const checkout = async (price, card, params = {}) => {
    const session = await stripe.checkout.sessions.create({
      mode: 'subscription',
      line_items: [{ price: price.id, quantity: 1 }],
      success_url: 'https://example.com/ok',
      ...params,
    });
    const fields = { card_number: card };
    if (!params.customer) fields.email = `buyer${Math.random().toString(36).slice(2, 8)}@example.com`;
    const res = await postForm(session.url, fields);
    if (res.status !== 303) throw new Error(`hosted Checkout answered ${res.status}: ${/<p class="error"[^>]*>([^<]*)</.exec(res.text)?.[1] ?? res.text.slice(0, 300)}`);
    return stripe.subscriptions.retrieve((await stripe.checkout.sessions.retrieve(session.id)).subscription);
  };

  // Trial through Checkout, no customer up front.
  const trialing = await checkout(basic, '4242424242424242', { subscription_data: { trial_period_days: 7 } });
  // Upgrade invoiced at once (proration lines).
  const upgraded = await checkout(basic, '4242424242424242');
  await stripe.subscriptions.update(upgraded.id, { items: [{ id: upgraded.items.data[0].id, price: pro.id }], proration_behavior: 'always_invoice' });
  // Cancel at period end, and an immediate cancel.
  const ending = await checkout(basic, '4242424242424242');
  await stripe.subscriptions.update(ending.id, { cancel_at_period_end: true });
  const canceled = await checkout(basic, '4242424242424242');
  await stripe.subscriptions.cancel(canceled.id);
  // Card that attaches but fails later: the charge at trial end fails (past_due, open invoice).
  await checkout(basic, '4000000000000341', { subscription_data: { trial_period_days: 3 } });
  // Schedules: one released, one canceled.
  const scheduled = await checkout(basic, '4242424242424242');
  const released = await stripe.subscriptionSchedules.create({ from_subscription: scheduled.id });
  await stripe.subscriptionSchedules.release(released.id);
  const scheduled2 = await checkout(basic, '4242424242424242');
  const toCancel = await stripe.subscriptionSchedules.create({ from_subscription: scheduled2.id });
  await stripe.subscriptionSchedules.cancel(toCancel.id);
  // An expired Checkout Session.
  const expired = await stripe.checkout.sessions.create({ mode: 'subscription', line_items: [{ price: basic.id, quantity: 1 }], success_url: 'https://example.com/ok' });
  await stripe.checkout.sessions.expire(expired.id);
  // A portal session with a flow.
  await stripe.billingPortal.configurations.create({
    business_profile: { privacy_policy_url: 'https://example.com/privacy' },
    features: { subscription_cancel: { enabled: true }, invoice_history: { enabled: true } },
  });
  const portalSession = await stripe.billingPortal.sessions.create({
    customer: trialing.customer,
    return_url: 'https://example.com/account',
    flow_data: { type: 'subscription_cancel', subscription_cancel: { subscription: trialing.id } },
  });
  // Eight days later: both trials have ended; the failing card's first charge and retry failed.
  await account.advanceTime({ seconds: 8 * DAY });
  // An advanced test clock.
  const now = Math.floor(Date.now() / 1000);
  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: now });
  const advancing = await stripe.testHelpers.testClocks.advance(clock.id, { frozen_time: now + DAY });

  const all = async (list) => {
    const out = [];
    for await (const x of list) out.push(x);
    return out;
  };
  const read = {
    customer: await all(stripe.customers.list({ limit: 100 })),
    product: await all(stripe.products.list({ limit: 100 })),
    price: await all(stripe.prices.list({ limit: 100 })),
    'checkout.session': await all(stripe.checkout.sessions.list({ limit: 100 })),
    subscription: await all(stripe.subscriptions.list({ status: 'all', limit: 100 })),
    subscription_schedule: await all(stripe.subscriptionSchedules.list({ limit: 100 })),
    invoice: await all(stripe.invoices.list({ limit: 100 })),
    'billing_portal.configuration': await all(stripe.billingPortal.configurations.list({ limit: 100 })),
    'billing_portal.session': [portalSession],
    'test_helpers.test_clock': [advancing, await stripe.testHelpers.testClocks.retrieve(clock.id)],
  };
  read.payment_method = [];
  read.subscription_item = [];
  read.line_item = [];
  for (const c of read.customer) read.payment_method.push(...(await all(stripe.paymentMethods.list({ customer: c.id, limit: 100 }))));
  for (const s of read.subscription) read.subscription_item.push(...(await all(stripe.subscriptionItems.list({ subscription: s.id, limit: 100 }))));
  for (const i of read.invoice) read.line_item.push(...(await all(stripe.invoices.listLineItems(i.id, { limit: 100 }))));
  await t.server.settle();
  const delivered = hooks.deliveries.map((d) => stripe.webhooks.constructEvent(d.rawBody, d.headers['stripe-signature'], SECRET));
  return { read, delivered, statuses: read.subscription.map((s) => s.status) };
}

describe.each([OLD, LATEST])('shapes through a Billing lifecycle at %s', (version) => {
  it('every object read back through the list endpoints has exactly the spec keys', async () => {
    const { read, statuses } = await lifecycle(version);
    // The scenario reached the states it is meant to cover.
    expect(statuses).toEqual(expect.arrayContaining(['active', 'canceled', 'past_due']));
    const problems = [];
    for (const [type, objects] of Object.entries(read)) {
      expect(objects.length, type).toBeGreaterThan(0);
      objects.forEach((obj, i) => problems.push(...deepProblems(obj, type, version, { where: `${type}[${i}] ${obj.status ?? ''}`.trim() })));
    }
    expect([...new Set(problems)]).toEqual([]);
  });

  it(`every delivered event and payload has the ${version} keys`, async () => {
    const { delivered } = await lifecycle(version);
    expect(delivered.length).toBeGreaterThan(20);
    const problems = [];
    for (const e of delivered) {
      problems.push(...shapeProblems(e, 'event', version, { where: `event ${e.type}` }));
      const type = e.data.object.object;
      if (SPEC[version][type]) problems.push(...deepProblems(e.data.object, type, version, { where: `${e.type} data.object` }));
    }
    expect([...new Set(problems)]).toEqual([]);
  });
});
